const phase=process.argv[2]||'after',out=path.join(root,'qa/adaptation-20261020',phase);fs.mkdirSync(out,{recursive:true});
const sizes=[{w:320,h:568,status:20,safe:0},{w:375,h:812,status:44,safe:34},{w:430,h:932,status:59,safe:34}].filter(s=>!process.argv[5]||process.argv[5].split(',').includes(String(s.w)));
const themes=(process.argv[3]||'ecology,culture,red,industry').split(','),scenes=(process.argv[4]||'home,quiz,revive').split(',');
const checks=[],events=[];
async function call(tool,args=[]){return new Promise((resolve,reject)=>{const c=spawn('/usr/local/bin/wechatide',['-c','Codex',tool,'--project',project,...args]);let text='';c.stdout.on('data',b=>text+=b);c.stderr.on('data',b=>text+=b);const t=setTimeout(()=>{c.kill();reject(Error(tool+' timeout'));},45000);c.on('close',code=>{clearTimeout(t);let r;try{r=JSON.parse(text.slice(text.indexOf('{')));}catch{return reject(Error(text));}events.push({tool,args,result:r});fs.writeFileSync(path.join(out,'events.json'),JSON.stringify(events,null,2));if(code||!r.ok||r.result?.success===false)return reject(Error(r.message||r.result?.error));resolve(r.result);});});}
function constrainedCSS(s,size){return s.replace(/@media\s*\(\s*(max|min)-(width|height)\s*:\s*(\d+)px\s*\)/g,(_,bound,axis,n)=>{const value=axis==='width'?size.w:size.h,active=bound==='max'?value<=Number(n):value>=Number(n);return active?'@media(min-width:0px)':'@media(max-width:0px)';}).replace(/([\d.]+)rpx\b/g,(_,n)=>(Number(n)*size.w/750)+'px').replace(/([\d.]+)v([wh])\b/g,(_,n,axis)=>(Number(n)*(axis==='w'?size.w:size.h)/100)+'px');}
function stage(size){for(const file of fs.readdirSync(path.join(root,'miniprogram/pages/game')).filter(x=>x.endsWith('.wxss'))){let s=constrainedCSS(fs.readFileSync(path.join(root,'miniprogram/pages/game',file),'utf8'),size);if(file==='index.wxss')s+='\n/* QA container only; never copied back to product. */\n.game-device{width:'+size.w+'px!important;height:'+size.h+'px!important;max-width:none!important;margin:0!important;transform-origin:0 0;}\n';fs.writeFileSync(path.join(project,'miniprogram/pages/game',file),s);}for(const component of ['game-button','mascot-actor']){const f='components/'+component+'/index.wxss';fs.writeFileSync(path.join(project,'miniprogram',f),constrainedCSS(fs.readFileSync(path.join(root,'miniprogram',f),'utf8'),size));}
 const info={windowWidth:size.w,windowHeight:size.h,screenWidth:size.w,screenHeight:size.h,statusBarHeight:size.status,safeArea:{top:size.status,left:0,right:size.w,bottom:size.h-size.safe,width:size.w,height:size.h-size.safe-size.status}},menu={left:size.w-94,right:size.w-7,top:size.status+6,bottom:size.status+38,width:87,height:32};
 const page=fs.readFileSync(path.join(root,'miniprogram/pages/game/index.js'),'utf8'),from='const i=wx.getWindowInfo?wx.getWindowInfo():wx.getSystemInfoSync(),m=homeLayout.metrics(i,wx.getMenuButtonBoundingClientRect?wx.getMenuButtonBoundingClientRect():null,skin.gameId);';assert(page.includes(from));fs.writeFileSync(path.join(project,'miniprogram/pages/game/index.js'),page.replace(from,'const i='+JSON.stringify(info)+',m=homeLayout.metrics(i,'+JSON.stringify(menu)+',skin.gameId); // QA metrics only\n'));
}
async function measure(selectors){const source='function(){return new Promise(resolve=>{const a='+JSON.stringify(selectors)+';const q=wx.createSelectorQuery();a.forEach(s=>q.selectAll(s).boundingClientRect());q.exec(rows=>resolve(Object.fromEntries(a.map((s,i)=>[s,rows[i]]))));});}';let r=await call('automation_evaluate',['--fn-source',source]);for(let i=0;i<4&&!r[selectors[0]];i++)r=r.result||r.data||r;return r;}
const selectors=['.game-device','.sound-button','.sound-settings-panel','.sound-settings-close','.sound-settings-actions button','.sound-settings-row','.sound-slider-row','.sound-switch-hit','#music-volume','#effects-volume','.theme-panel','.theme-heading>image','.theme-heading>.h1','.activity-header','.home-title-label','.activity-points','.activity-shortcut','.panel-scroll-frame','.panel-body','.panel-footer','#footer-primary','.quest-banner','.quest-companion','.quest-banner-copy','.question-card','.question-title','.option','.option-text','.modal-mask','.theme-modal','.modal-decoration','.modal-topbar','.modal-close','.modal-inner','.modal-actions','#modal-primary','.route-stop.is-reached','.chapter-mascot','.route-caption','.profile-card','.profile-card>.h2','.profile-link','.certificate-paper','.certificate-preview','.certificate-switch button'];
(async()=>{try{for(const size of sizes){
 stage(size);await call('simulator_refresh');await call('automation_page_action',['--action','getData','--data-path','route','--wait-for-selector','.game-device']);
 for(const theme of themes)for(const scene of scenes){
 await call('automation_navigate',['--action','reLaunch','--url','/pages/game/index?theme='+theme+'&review=1&controls=0&scenario='+(scene==='rules'||scene==='settings'?'home':scene==='profile'?'home&route=profile':scene)]);
 if(scene==='settings')await call('automation_element_action',['--action','tap','--selector','#sound-settings','--wait-for-selector','#sound-settings']);
 if(scene==='rules')await call('automation_element_action',['--action','trigger','--selector','#footer-primary','--type','action','--detail','{}','--wait-for-selector','#footer-primary']);
 if(scene==='quiz'){const opts=['莲','棉花','茶树','柑橘'];await call('automation_page_action',['--action','setData','--patch',JSON.stringify({'challenge.question.title':'湘潭县重点发展的“湘莲”产业与哪种植物相关？',options:opts.map((text,index)=>({index,letter:String.fromCharCode(65+index),text}))})]);}
 const r=await measure(selectors),issues=[];const test=(ok,label)=>{if(!ok)issues.push(label);};
 const sound=r['.sound-button'][0];if(sound){test(sound.width>=44&&sound.height>=44,'sound touch target');test(sound.top>=size.status&&sound.right<=size.w-94,'sound stays clear of status and capsule');}
 const box=r['.game-device'][0];test(Math.abs(box.width-size.w)<1&&Math.abs(box.height-size.h)<1,'container size');
 if(scene==='settings'){const p=r['.sound-settings-panel'][0];test(p.left>=12&&p.right<=size.w-12,'settings horizontal bounds');test(p.top>=size.status+44&&p.bottom<=size.h-size.safe,'settings safe area');test(r['.sound-settings-close'][0].width>=44&&r['.sound-settings-close'][0].height>=44,'settings close target');test(r['.sound-settings-actions button'].every(b=>b.height>=44&&b.width>=44),'settings actions targets');test(r['.sound-settings-row'].every(b=>b.height>=44),'switch row targets');test(r['.sound-slider-row'].every(b=>b.height>=44),'slider row targets');test(['#music-volume','#effects-volume'].every(k=>r[k][0].left>=p.left&&r[k][0].right<=p.right),'sliders inside sheet');}
 if(scene==='home'){test(r['.activity-shortcut'].every(x=>x.height>=44),'shortcut targets');test(r['.activity-points'][0].height>=44,'points target');const f=r['.panel-footer'][0];test(f.bottom<=size.h+1,'footer inside viewport');test(f.bottom-(r['#footer-primary'][0]?.bottom||0)>=size.safe,'home safe area');test(r['.panel-scroll-frame'][0].height>=120,'map viewport');}
 if(scene==='quiz'){const frame=r['.panel-scroll-frame'][0],footer=r['.panel-footer'][0],actor=r['.quest-companion'][0],copy=r['.quest-banner-copy'][0];test(copy.right+8<=actor.left,'actor copy gap');test(r['.option'].every(x=>x.height>=44),'option targets');test(footer.bottom<=size.h-size.safe+1,'quiz safe area');test(frame.height>=120,'answer scroll area');test(r['.option-text'].every((x,i)=>x.height<=r['.option'][i].height),'option copy fits');test(r['.question-title'][0].right<=r['.question-card'][0].right,'question inside card');test(r['.option'][0].bottom<=frame.bottom+1,'first option visible before scrolling');}
 if(['revive','locked','rules'].includes(scene)){test(r['.modal-close'][0]?.height>=44,'close target');const modal=r['.theme-modal'][0],actions=r['.modal-actions'][0],inner=r['.modal-inner'][0];test(modal.top>=size.status+38,'modal below capsule');test(modal.bottom<=size.h-size.safe+1,'modal safe area');test(actions.bottom<=modal.bottom+1,'modal actions inside');test(inner.height>=50,'modal readable scroll area');}
 if(scene==='profile'){test(r['.profile-card>.h2'][0].right<=r['.profile-card'][0].right,'profile title inside card');test(r['.profile-link'].every(b=>b.height>=44),'profile link targets');await call('automation_element_action',['--action','scrollTo','--selector','.panel-body','--x','0','--y','9999']);}
 if(scene==='certificate'){test(r['.certificate-preview'][0].right<=r['.certificate-paper'][0].right,'certificate image inside paper');test(r['.certificate-switch button'].every(b=>b.height>=44),'certificate switch targets');test(r['.panel-footer'][0].bottom<=size.h-size.safe+1,'certificate safe area');}
 if(scene==='quiz'){const file=theme+'-'+size.w+'x'+size.h+'-quiz-initial.png';if(size.w<=390)await call('simulator_screenshot',['--path',path.join(out,file),'--optimize','false','--wait-for-selector','.question-title']);await call('automation_element_action',['--action','scrollTo','--selector','.panel-body','--x','0','--y','9999']);const scrolled=await measure(['.panel-scroll-frame','.option']);test(scrolled['.option'].at(-1).bottom<=scrolled['.panel-scroll-frame'][0].bottom+1,'last option scrolls fully above footer');r.scrolled=scrolled;}
 const data=(await call('automation_page_action',['--action','getData','--data-path','shellStyle']));test(data.data.includes('--status:'+size.status+'px;'),'window metrics applied');
 const scale=Math.min(1,390/size.w,844/size.h);if(scale<1)await call('automation_page_action',['--action','setData','--patch',JSON.stringify({shellStyle:(typeof data==='string'?data:data.data||'')+';transform:scale('+scale+');'})]);
 const file=theme+'-'+size.w+'x'+size.h+'-'+scene+'.png';const ready={settings:'.sound-settings-panel',home:'.route-canvas',quiz:'.question-title',revive:'.revive-companion',locked:'.rest-companion',rules:'.chapter-welcome',profile:'.profile-card',certificate:'.certificate-paper'}[scene];await call('simulator_screenshot',['--path',path.join(out,file),'--optimize','false','--wait-for-selector',ready]);
 checks.push({theme,scene,size,passed:issues.length===0,issues,rect:r,screenshot:file,screenshotScale:scale});fs.writeFileSync(path.join(out,'checks.json'),JSON.stringify({scope:'Native WeChat renderer with constrained container CSS and injected window/capsule metrics. Host simulator remains 390x844; not a physical device or native model switch.',passed:checks.every(x=>x.passed),checks},null,2));console.log((issues.length?'FAIL ':'PASS ')+theme+' '+size.w+' '+scene+' '+issues.join(', '));
 }
 }}finally{for(const method of ['getWindowInfo','getMenuButtonBoundingClientRect'])await call('automation_wx_api',['--action','restore','--method',method]);for(const dir of ['pages/game','components/game-button','components/mascot-actor'])for(const file of fs.readdirSync(path.join(root,'miniprogram',dir)).filter(x=>x.endsWith('.wxss')))fs.copyFileSync(path.join(root,'miniprogram',dir,file),path.join(project,'miniprogram',dir,file));fs.copyFileSync(path.join(root,'miniprogram/pages/game/index.js'),path.join(project,'miniprogram/pages/game/index.js'));await call('simulator_refresh');}
 if(checks.some(x=>!x.passed))process.exitCode=1;
})().catch(e=>{fs.writeFileSync(path.join(out,'error.txt'),e.stack);console.error(e);process.exitCode=1;});
